import { Db, EventHandler, Topics } from '@hr/common';
import { DocumentService } from '../services/document.service';

/** Payslip PDFs generated by payroll are registered here so employees find them in their document list. */
export function documentConsumers(db: Db): Record<string, EventHandler> {
  const svc = new DocumentService(db);
  return {
    [Topics.PAYSLIP_GENERATED]: async (ev, conn) => {
      const p = ev.payload as any;
      await svc.registerSystemDocument({ ownerEmployeeId: p.employeeId, categoryCode: 'PAYSLIP', title: `Payslip ${p.month}`, fileName: p.fileName, storagePath: p.storagePath, sha256: p.sha256, sizeBytes: p.sizeBytes, source: 'PAYSLIP' }, conn);
    },
  };
}
